  $(CC) -o $(NAME) $(MAIN) $(OBJ) $(LIB) $(FLAGS_DEBUG)
  @valgrind ./$(NAME)
  @echo -e "\033[32mDebug mode done !\033[0m"

tests_run:  all
  @$(CC) -o $(TEST) $(SRC) $(TESTSRC) $(LIB) $(FLAGS_TU)
  @./$(TEST)
  gcovr

clean:
  @make clean -C ./lib/my/

fclean:  clean
  @rm -frv $(NAME)
  @rm -frv $(TEST)
  @rm -frv $(OBJ)
  @rm -frv $(CRITERION)
  @rm -frv $(EMACS)
  @rm -frv $(TILDE)
